function unpaired(ids: number[]): number {
  // Every id appears twice except one. Return it using O(1) extra space.
  return -1;
}

console.log(unpaired([104, 77, 9, 104, 9]));

solution:
function unpaired(ids: number[]): number {
  let x = 0;
  for (const id of ids) x ^= id;
  return x;
}
